const event = $json || {};
const execution = event.execution || {};
const workflow = event.workflow || {};
const error = execution.error || event.error || {};
const executionReference = execution.id ? String(execution.id) : null;
const workflowReference = workflow.id ? String(workflow.id) : (workflow.name || null);
const failedNode = execution.lastNodeExecuted || error.node?.name || null;
const eventKey = [workflowReference || 'unknown-workflow', executionReference || 'unknown-execution', failedNode || 'unknown-node'].join(':').slice(0,200);
return [{json:{event_key:eventKey,job_id:null,correlation_id:null,workflow_reference:workflowReference,execution_reference:executionReference,failed_node:failedNode,error_class:String(error.name || error.httpCode || error.message || 'workflow_error').slice(0,80)}}];
